// The main thread's half of the GPU bridge.
//
// Loon's VM is synchronous and WebGPU is not, so the VM runs in a worker and
// blocks on `Atomics.wait` while this file does the asynchronous part. The
// protocol is deliberately small: a control word says whose turn it is, a
// request is passed as a structured-clone message, and the reply is written
// into a SharedArrayBuffer before the worker is woken.
//
// Nothing here knows anything about Loon. It receives WGSL — generated by the
// same emitter a desktop build hands to wgpu — plus buffers and a work count.

// Control word slots, in Int32 units.
const STATE = 0; // 0 = worker waiting, 1 = reply ready
const STATUS = 1; // 0 = ok, 1 = error
const LENGTH = 2; // reply byte length
const HEADER_WORDS = 4;

/// Set up a worker that can call into WebGPU synchronously.
///
/// `replyBytes` bounds the largest single readback; a download larger than
/// this is reported rather than truncated.
export async function attachGpuBridge(worker, { replyBytes = 1 << 24 } = {}) {
  if (!navigator.gpu) {
    throw new Error('this browser has no WebGPU');
  }
  const adapter = await navigator.gpu.requestAdapter();
  if (!adapter) {
    throw new Error('no WebGPU adapter available');
  }
  const device = await adapter.requestDevice();
  const info = adapter.info ?? {};
  const name = [info.vendor, info.architecture].filter(Boolean).join(' ') || 'webgpu';

  const control = new SharedArrayBuffer(HEADER_WORDS * 4 + replyBytes);
  const words = new Int32Array(control, 0, HEADER_WORDS);
  const payload = new Uint8Array(control, HEADER_WORDS * 4);

  // Device-side buffers, keyed by the host's heap slot — the same identity the
  // Rust side uses, so residency is something both ends agree about by name.
  const buffers = new Map();
  const pipelines = new Map();

  const encoder = new TextEncoder();

  function reply(status, bytes) {
    if (bytes && bytes.byteLength > payload.byteLength) {
      status = 1;
      bytes = encoder.encode(
        `a readback of ${bytes.byteLength} bytes exceeds the ${payload.byteLength}-byte reply buffer`,
      );
    }
    const len = bytes ? bytes.byteLength : 0;
    if (len) payload.set(bytes, 0);
    Atomics.store(words, LENGTH, len);
    Atomics.store(words, STATUS, status);
    Atomics.store(words, STATE, 1);
    Atomics.notify(words, STATE);
  }

  function pipelineFor(shader, entry) {
    let p = pipelines.get(shader);
    if (!p) {
      const module = device.createShaderModule({ code: shader });
      p = device.createComputePipeline({
        layout: 'auto',
        compute: { module, entryPoint: entry },
      });
      pipelines.set(shader, p);
    }
    return p;
  }

  async function handle(req) {
    switch (req.op) {
      case 'name':
        return encoder.encode(name);

      case 'upload': {
        const bytes = req.bytes;
        const buf = device.createBuffer({
          size: Math.max(bytes.byteLength, 4),
          usage:
            GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC,
        });
        device.queue.writeBuffer(buf, 0, bytes);
        buffers.get(req.id)?.destroy?.();
        buffers.set(req.id, buf);
        return null;
      }

      case 'dispatch': {
        // The uniform block is `n` followed by every scalar, matching what the
        // WGSL emitter wrote into `struct Params`, padded to 16 bytes.
        const scalars = req.scalars;
        const uniformWords = 1 + scalars.length;
        const padded = Math.ceil(uniformWords / 4) * 4;
        const uniform = new ArrayBuffer(padded * 4);
        new Int32Array(uniform, 0, 1)[0] = req.n;
        if (scalars.length) new Float32Array(uniform, 4, scalars.length).set(scalars);
        const uniformBuf = device.createBuffer({
          size: uniform.byteLength,
          usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        });
        device.queue.writeBuffer(uniformBuf, 0, uniform);

        const pipeline = pipelineFor(req.shader, req.entry);
        const entries = [{ binding: 0, resource: { buffer: uniformBuf } }];
        req.buffers.forEach((id, slot) => {
          const buf = buffers.get(id);
          if (!buf) throw new Error(`buffer ${id} is not on the device`);
          entries.push({ binding: slot + 1, resource: { buffer: buf } });
        });

        const bindGroup = device.createBindGroup({
          layout: pipeline.getBindGroupLayout(0),
          entries,
        });

        const cmd = device.createCommandEncoder();
        const pass = cmd.beginComputePass();
        pass.setPipeline(pipeline);
        pass.setBindGroup(0, bindGroup);
        // Workgroup size is 64 in the emitted shader; the bounds check inside
        // it discards the overshoot from rounding up.
        pass.dispatchWorkgroups(Math.max(1, Math.ceil(req.n / 64)), 1, 1);
        pass.end();
        device.queue.submit([cmd.finish()]);
        return null;
      }

      case 'download': {
        const src = buffers.get(req.id);
        if (!src) throw new Error(`buffer ${req.id} is not on the device`);
        const size = Math.max(req.byteLength, 4);
        const staging = device.createBuffer({
          size,
          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
        });
        const cmd = device.createCommandEncoder();
        cmd.copyBufferToBuffer(src, 0, staging, 0, size);
        device.queue.submit([cmd.finish()]);
        await staging.mapAsync(GPUMapMode.READ);
        const copy = new Uint8Array(staging.getMappedRange().slice(0, req.byteLength));
        staging.unmap();
        staging.destroy();
        return copy;
      }

      case 'evict': {
        buffers.get(req.id)?.destroy?.();
        buffers.delete(req.id);
        return null;
      }

      default:
        throw new Error(`unknown device operation '${req.op}'`);
    }
  }

  worker.addEventListener('message', async (e) => {
    if (!e.data || e.data.kind !== 'gpu') return;
    try {
      const bytes = await handle(e.data);
      reply(0, bytes);
    } catch (err) {
      reply(1, encoder.encode(String(err && err.message ? err.message : err)));
    }
  });

  worker.postMessage({ kind: 'gpu-ready', control });
  return { name, control };
}
